INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Car War: Transform Battle Machines', 'City robot battle is raging on - take part in a full scaled robot invasion! Become a fighting robot and wreak havoc - defeat armies of shooting robots and humans alike. Fight your robotic battle your way - shoot, throw, transform and unleash your ultimate robot smash power in the battle of city robots!' FROM games WHERE igdb_id = 187472 ON CONFLICT (game_id, language_code) DO NOTHING;
