INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mars Accident', 'Mars Accident is a 2d shooter where the player dodges a falling and flying saucer. The only thing that raises it is the laser energy bunches that the hero releases and which destroy the aliens. The goal of the game is to fight off the alien attack and protect your spaceship from the attack.' FROM games WHERE igdb_id = 157477 ON CONFLICT (game_id, language_code) DO NOTHING;
