INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '神启神落', '这是一款魔幻类地牢探险、角色扮演多玩法游戏，玩家扮演神启者，不断的招集神落者（游戏中的英雄）对抗挑战，目前开发试炼之地模式，支持选择的英雄提升等级及属性，同时游戏具有独特的魂体转化系统，每一次对噬魂者的毁灭都对应了新的神落者的重生，在之后的其它模式，玩家会召唤这些英雄参与群体战斗' FROM games WHERE igdb_id = 152760 ON CONFLICT (game_id, language_code) DO NOTHING;
