INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doomsday: Last Survivors', 'Doomsday: Last Survivors is a zombie survival strategy game with multiplayer online competition and real-time strategy elements. Set in a near future where zombies have taken over the world, survivors must fight for their lives and for the future of humanity. As the Commander, it''s your duty to lead your fellow survivors to build their Shelter, explore fog-filled areas, and fight the zombies and rival factions! Enjoy zombie games, survival games, and strategy games? Doomsday: Last Survivors has got you covered!' FROM games WHERE igdb_id = 187739 ON CONFLICT (game_id, language_code) DO NOTHING;
