INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Slam Tennis', 'Play the 4 Grand Slam Tournaments in this higly realistic tennis game. Play solo or against friends and family in the local multiplayer split screen mode. Tons of 3D animations and all real tennis ball effects/shots makes Grand Slam Tennis the most playable tennis game on eShop! Main Features: -Full 3D -8 Players including 4 Female Players -lift/slice/volley/smash/lob/passing shots -Easy Joy-Con or Pro Controller controls -Solo or Local Split Screen Multiplayer -Realistic Tennis Sounds -Tournament Mode -Ball Machine Training Mode Win the Grand Slam!' FROM games WHERE igdb_id = 149301 ON CONFLICT (game_id, language_code) DO NOTHING;
