INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('forest-camp-story', 174297, '2021-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5oa8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1rlk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forest Camp Story', 'The great outdoors are calling! Create and run your own campground in this business management sim. Get a lay of the land and find the best places to camp. Before you know it, customers will be setting up tents and taking pictures, making memories that will last a lifetime. But it''s not all about peace and solitude. With activities like bird watching, fly fishing, and horse riding, there''s no shortage of ways to show your campers a good time! No camping experience? No problem! Set up guided tours to show new campers the ropes, and they''ll soon be coming back for more. If you play your cards right, you might get visits from rabbits, squirrels, and other cute critters too! Don''t be afraid to branch out and grow your business. Set up a camping goods store in nearby towns to earn extra cash and attract new customers. Get more people interested in your wares, and you might just spark a nationwide camping craze... Answer the call of the wild and start creating the camp of your dreams!' FROM games WHERE igdb_id = 174297 ON CONFLICT (game_id, language_code) DO NOTHING;
