INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Somniphobia', 'Survival horror in a girl''s nightmare. Complete puzzles and survive in a nightmarish hand-painted world of Susan''s mind. If she wakes up, she''ll have the same dream again. You must keep all of her nasty thoughts and memories away from you to stop her from waking up.' FROM games WHERE igdb_id = 152472 ON CONFLICT (game_id, language_code) DO NOTHING;
