INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MasterChef: Learn to Cook!', 'If you enjoy cooking games or want to explore new recipes in a fun and interactive way, then MasterChef: Learn to Cook! It might be worth checking out. Get matched with other players around the globe. Choose your ingredients, slice, prepare, plate and serve delicious dishes with style in fun mini-games! The MasterChef judges will evaluate your dish based on your performance and speed. Complete and unlock new recipes, challenges, and mini-games along your cooking journey. MORE THAN 120 RECIPES!' FROM games WHERE igdb_id = 299804 ON CONFLICT (game_id, language_code) DO NOTHING;
