INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doki Doki Daigaku', 'When a computer glitch mysteriously ruins your perfect GPA, you''re forced to attend summer school at an all-girls university to maintain your scholarship. The change of scenery isn''t so bad—until your former high school rival takes roll. With your vacation ruined, can you drag the struggling members of WISH back into the spotlight, or is this the end of your dreams?' FROM games WHERE igdb_id = 215280 ON CONFLICT (game_id, language_code) DO NOTHING;
