INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkness and Light', 'Darkness and Light is a single player 2D platformer game about The Soul on its path to the final destination. Explore flying through avenue, mountain range, city lights, and darkness. Experience downfalls and changes, endings and new beginnings, crying and laughter. Solve puzzles and mazes, gather knowledge, fill with love, collect all the keys that open magical doors, and enlighten the soul to ascend.' FROM games WHERE igdb_id = 159152 ON CONFLICT (game_id, language_code) DO NOTHING;
