INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Miserable Crimson Hooded Girl', 'Once upon a time, there was a miserable girl in a crimson hood. Her mother was unwell, so the girl was sent away to go stay with her grandmother, who lived deep within the woods in a strange house. People say that around those parts there resides a monster called the Gobbler, who preys on the weak...' FROM games WHERE igdb_id = 125041 ON CONFLICT (game_id, language_code) DO NOTHING;
