INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charlie: The Legend', 'Equip yourself with the best weapons and get ready to face your worst fears... Charlie: The Legend aspires to become a must have for all those who enjoy multiplayer horror games. Charlie is an asymmetrical multiplayer horror video game in which 4 Survivors must face a diabolical doll possessed by a demon. It''s up to you! Play as Charlie and defeat the other players or take on Charlie as a survivor.' FROM games WHERE igdb_id = 172022 ON CONFLICT (game_id, language_code) DO NOTHING;
