INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ultimate-bumper-cars-dodgems', 164765, '2021-08-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pbf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10sq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Bumper Cars: Dodgems', 'Ultimate Bumper Cars is a realistic Bumper Car Simulator with multiplayer support and realistic physics. This brilliant attraction is fun for all ages. Dodgems or Bumper Cars will always be remembered as one of the longest running and most successful attractions in the amusement industry. No other ride can compete with Dodgems when it comes to family fun and entertainment. Bumper-to-bumper traffic never been this fun – or bumpy! Grab all your friends and family for fantastic fun on our classic Dodgems simulator game. Step into the dodgem arena, take control of your own dodgem car, and race around as you try to avoid the chaos! Jump into one of 16 cars, put your foot on the accelerator, and try to eliminate your rivals! But watch out for the guy behind you; he has a wild look in his eye!' FROM games WHERE igdb_id = 164765 ON CONFLICT (game_id, language_code) DO NOTHING;
