INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('offroad-driving-simulator-4x4-trucks-and-suv-trophy', 147933, '2021-03-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3qjq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard9v.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Offroad Driving Simulator 4x4: Trucks & SUV Trophy', 'Go for extreme offroad drive, desert, forests, mud road and snowy wastes are waiting for a good offroad SUV driver! Try our new 4x4 offroad driving simulator - a cool offroad driver game with hill climb driving, lots of cool 4x4 and 6x6 trucks and tons of offroad game fun! > Go on an epic offroad trip across FOUR REGIONS > Drive DOZENS of various TRUCKS and SUVs > Purchase VISIBLE UPGRADES to improve your driving > Use WINCH, DIFF LOCK and other special mechanisms > Complete special MISSIONS and CHALLENGES for rewards Offroad championship! Global offroad driving contest is about to begin! Prove that your are the best at offroad driving across four regions with different conditions and trials on trucks of three various types. Prepare your self for a lot of extreme challenge - start your engine and go offroad! Powerful 4x4 cars! Get behind the wheel of all sorts of offroad vehicles of various types and classes, from a regular 4x4 SUV to gigantic monster-truck. Each is equipped with special offroad driving devices, like winch, and can be visibly upgraded for better performance. Use all you have to get and edge in driving! Driving challenge! Face various challenges of the extreme offroad - cross rivers and snowy forests, climb up hill and crawl over rocks. And complete various additional challenges and mission to get cool rewards. Make your own way to the title of the champion! Take part in Pathfinder trials - the most extreme offroad driving tournament ever!' FROM games WHERE igdb_id = 147933 ON CONFLICT (game_id, language_code) DO NOTHING;
