INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godfall: Challenger Edition', 'Instantly unleash Godfall’s power! Godfall Challenger Edition immediately unlocks a maximum level Valorplate, spoils you with skill points, and equips you with a spread of deadly weapons. Challenge all three end-game modes Lightbringer, Dreamstones, and the Ascended Tower of Trials. Vanquish your enemies and be rewarded with loot worthy of a true Valorian. Loot and slash in up to 3-player matchmade co-op to show your skill, perfect your build, and smash your enemies.' FROM games WHERE igdb_id = 185638 ON CONFLICT (game_id, language_code) DO NOTHING;
