INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cargo Transportation: Low Poly', 'Cargo Transportation: Low Poly is a game in which the player needs to take all the cargo (crates, barrels), through obstacles to the finish line. Cargo transportation will be carried out on one of the 4 cars to choose from, but in order for this choice to appear, you need to earn game coins to purchase new cars. The cars in the game are different: a pickup truck, a narrow truck, a mullion truck, and a large truck. Depending on the level, the player decides which car is more convenient for him to transport the cargo. INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 144914 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
