INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Random Maze', '一个忘记自己姓名与过去的人，在突然出现的神秘人物的帮助下，从一个空无一人的医院开始探索自己的过去。只有取回真实，才能从这里离开，即使……真相不像你所期待的那样，他也依然盼望着他的未来。' FROM games WHERE igdb_id = 150481 ON CONFLICT (game_id, language_code) DO NOTHING;
