INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half Past Fate: Romantic Distancing', 'Finding true love is hard enough when it’s in person! Build a relationship through the screen as a couple copes with lockdown life by staying connected online! Will their love be loud and clear, or will their signals fade away?' FROM games WHERE igdb_id = 143589 ON CONFLICT (game_id, language_code) DO NOTHING;
