INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The TET Offensive', 'You are a Viet Cong during the Tet Offensive, a massive surprise attack that changed the course of the Vietnam War. Your objective is to take the American''s Base, you can stealth your way by digging tunnels and avoiding detection, or release all bullets from your AK-47 into the enemy, the way you conquer the Base is your choice, but remember... there are consequences.' FROM games WHERE igdb_id = 323804 ON CONFLICT (game_id, language_code) DO NOTHING;
