INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starlight Alliance', 'Starlight Alliance is an action RPG, featuring two playable characters – Cyris and Lea. If you like fast third-person shooter gameplay with plenty of character development, exploration, and puzzle-solving, Starlight Alliance is the game for you! Likewise, if you’re into shooting annoying drones that tell you to get back to work, we got you covered. Starlight Alliance has it all.' FROM games WHERE igdb_id = 172849 ON CONFLICT (game_id, language_code) DO NOTHING;
