INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utawarerumono: ZAN 2', 'Utawarerumono: ZAN 2 is a 3D Action RPG playstyle based on Utawarerumono: The Mask of Deception. Introducing new scenarios, the main story, "Hakuoro Arena," is based on Utawarerumono: Mask of Truth and told in a "military chronicle" style. You can play either solo or coop (up to four players online). This mode features exclusive enemies, maps, and more.' FROM games WHERE igdb_id = 145490 ON CONFLICT (game_id, language_code) DO NOTHING;
