INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Never Return', 'Never Return is a 3D free-to-view randomised dungeon action game with light Roguelike elements. With a rich weapon and talent system, the game''s real-time combat feels solid and varied, allowing players to build according to their own fighting style and gaming habits. every battle is a dizzying experience, and the challenge of random maps and enemies keeps going further and further.' FROM games WHERE igdb_id = 165122 ON CONFLICT (game_id, language_code) DO NOTHING;
