INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('winterlore-ii', 174284, '2021-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55d1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3j3w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winterlore II', 'There''s a new obstacle in Moroi Springs. What is it this time around? Follow the story of Ozana and her new found powers. The traditions she knew inside out bring a new meaning to her way of life and to Mamaie''s customs. She''ll mend herbs, brew concoctions and cook sweets for the solstice feast. Along the way she''ll encounter guests bringing in new beginnings, while others appear uninvited into the home. Winterlore II is the second game set in the universe of Moroi Springs. Uncover the region of Moroi Springs and its mysteries. Discover lost traditions and folklore by solving puzzles. Immerse yourself in the narrative through hand-crafted graphics and an atmospheric soundtrack. Unveil the hidden story by examining old objects and connect the dots.' FROM games WHERE igdb_id = 174284 ON CONFLICT (game_id, language_code) DO NOTHING;
