INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Absolutely Hilarious Cat Game', 'The Absolutely Hilarious Cat Game is exactly what you would expect it to be, the only thing is, things take a dark turn when you wake up in a place you shouldn''t be... Wrong place wrong time I suppose... Watch out, Felines are on the prowl in Ginger''s Peak. Get the job DONE, then GET OUT!' FROM games WHERE igdb_id = 153959 ON CONFLICT (game_id, language_code) DO NOTHING;
