INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'To the End 2', 'The long awaited sequel for To The End is finally here. Discover 13 challenging new levels in beautiful 3D and find the path all the way through to the end with a simple one-touch control. Let the atmosphere of To the End 2 take you away on a peaceful, yet frustrating journey through space, snow, water and mines. With only four lives there is not much room for mistakes... Can you make it to the end?' FROM games WHERE igdb_id = 174304 ON CONFLICT (game_id, language_code) DO NOTHING;
