INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('smash-boats', 147677, '2021-02-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4p1q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb0w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smash Boats', 'Smash Boats is an action game with a seemingly simple goal inspired by the golden age of arcade games, which is to smash everything in your quest to unlock and conquer all the pools! Sounds easy; but, with relentless enemies, zany Mayday events, and unusual water hazards trying to hinder your progress, the goal is anything but easy! Smash Boats includes many unique pools to smash in, including a toy chest, a pool table and even a toilet! The game features 16 distinctive boats that have to be earned via sinking enemies and/or collecting stars by clearing stages. Each boat has a unique smash-ability, such as: frying pan, shark bite, lasers, water-pound, and many more. And with other moves like submerge, ram, backward ram, power-turn and brake, the player has an assortment of smash moves at their disposal to conquer stages, and collect stars. Collect enough stars and you will unlock new boats and pools! Can you become the ultimate Smasher by completing the insane shower pool?' FROM games WHERE igdb_id = 147677 ON CONFLICT (game_id, language_code) DO NOTHING;
