INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Festival', 'Cooking Festival is a delicious management sim that will let you bake, fry and grill around the world! Become the master chef the cooking world has been waiting for and whip up some homemade pancakes, grill juicy ribs, bake aromatic original Italian pizzas, and serve delicious ice cream that everyone loves! Cooking is incredibly easy - just tap & serve! Start exploring the world and prepare whatever cuisine you like!' FROM games WHERE igdb_id = 147632 ON CONFLICT (game_id, language_code) DO NOTHING;
