INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maze Banquet', 'A nameless boy emerges from the darkness. His creator led him to the banquet with a letter: "Observe the guests and appoint one as the Maze King". Deprived of his voice, the boy heads to the Maze Banquet. He encounters the four creations at the entrance... from there a mysterious adventure unfolds!' FROM games WHERE igdb_id = 155950 ON CONFLICT (game_id, language_code) DO NOTHING;
