INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loosepo', 'This is an ultra-lightweight Top-Down shooting game with roguelike elements. You need to constantly recycle your empty wine bottles to replenish ammunition. Use the initial props cards and the upgrade cards in the game to build a powerful butt baby, and then help it defeat the evil rotten demons' FROM games WHERE igdb_id = 184538 ON CONFLICT (game_id, language_code) DO NOTHING;
