INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabin Fever', 'An off-grid cabin. A tech-savvy loner. One ray of sunshine in a bleak, ruined world. Cabin Fever is a sweet, funny, slice-of-life romantic visual novel with meaningful player choices, multiple endings to explore, and a story that will touch your heart. Experience a budding friendship - and a blossoming romance - as you open up, make choices, and explore multiple endings. The world may seem bitter and bleak… But your story doesn''t have to be.' FROM games WHERE igdb_id = 154797 ON CONFLICT (game_id, language_code) DO NOTHING;
