INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Zombie Death Ball', 'Ultimate Zombie Death Ball is a 1v1 arena sports game set in a zombie apocalypse. The object of the game is to get a ball in your opponent’s net, while being chased by a hoard of hungry zombies. Also, the ball is electrified, and will stun you if you kick it. Luckily, the zombies can kick it for you.' FROM games WHERE igdb_id = 194815 ON CONFLICT (game_id, language_code) DO NOTHING;
