INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-adventure-of-ravi-n-navi', 180982, '2021-11-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59be.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar19a6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventure of Ravi ''n'' Navi', '"Radiant Rabbits" is a village where rabbits and fairies live in peace. Ravi and Navi have to defeat the great demon king "Shivarra", who is planning to destroy the village! The main character, rabbit "Ravi", joins forces with fairy "Navi" and sets out on an adventure to collect the "Sacred Carrot", the source of happiness hidden by Shivarra. On their way, they are greeted by a variety of tricks and unique characters. They can compete in boat races with beaver, ride a minecart down a mining railroad, and even play retro arcade games! As they progress through the story, they can take advantage of the increasing number of actions, use the coins they''ve collected to buy dress-up items in the souvenir shop, and more... There''s so much to do in Ravi world! Let''s go on a great adventure with Ravi ''n'' Navi!' FROM games WHERE igdb_id = 180982 ON CONFLICT (game_id, language_code) DO NOTHING;
