INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pippu: Bauble Quest', 'Pippu is a heroic little creature from the world of the Beandrops. One day her planet is visited by hostile aliens called the Obkins, who travel from place to place stealing precious treasures to power their dangerous and wacky machinery. Run, climb and swim your way through 14 worlds to bash the baddies and save your planet. Features: Colorful, vibrant worlds with lots of nooks and crannies to explore. A kooky cast of weird and wonderful characters to meet. Collect all 56 Baubles to restore your world to its full glory. Fun for all the family, young and old, beginner or seasoned gamer.' FROM games WHERE igdb_id = 165602 ON CONFLICT (game_id, language_code) DO NOTHING;
