INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bring-your-own-oxygen', 186216, '2021-05-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4mqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf3x5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bring Your Own Oxygen', 'A game about disability and attempting to achieve the usual. Explore Elery as a 10 year old kid just trying to finish their town history project, and uncover the town''s secrets, or don''t. Bring Your Own Oxygen is a story about a chronically ill child trying to do what every other kid in Elery does, only to find some strange truths about the world around them. Whether you report it or not, the consequences may be more than you think.' FROM games WHERE igdb_id = 186216 ON CONFLICT (game_id, language_code) DO NOTHING;
