INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Investigation 2: Homicide', 'Famous police detective, Agent Sarah, is on her way to investigate yet another unsolvable crime! Her journey will take her deep into a web of deceit and uncover a strange revenge plot linked to a long-forgotten case. In the world of puzzles and mystery, Sarah would have never expected to stumble into true love. Follow Sarah as she confronts incredible challenges in her latest adventure!' FROM games WHERE igdb_id = 177055 ON CONFLICT (game_id, language_code) DO NOTHING;
