INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stories of Liane', '300 years into the future: Earth is uninhabitable. Only the most powerful have escaped searching for a new home for humanity. Stories of Liane is an experimental experience that explores the narrative and visuals of a dark dystopian atmosphere through multiple different perspectives and settings. This is a collection of stories from several characters to explore humanity''s future in this dark future.' FROM games WHERE igdb_id = 144603 ON CONFLICT (game_id, language_code) DO NOTHING;
