INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DeadLock', 'In DeadLock, the player must connect the processor and the resources it needs in the appropriate order to prevent ''DeadLock'' from occurring. More and more targets need to be scheduled, and new kinds of resources emerge. It''s up to the player to efficiently schedule without generating ''Deadlock''.' FROM games WHERE igdb_id = 166073 ON CONFLICT (game_id, language_code) DO NOTHING;
