INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 6: Collector''s Edition', 'Welcome to Yara, a tropical paradise frozen in time. Far Cry 6 thrusts players into a modern-day guerrilla revolution. As dictator of Yara, Anton Castillo is intent on restoring his nation back to its former glory by any means, with his son, Diego, following in his bloody footsteps. Become a guerrilla fighter and liberate Yara. Pick up the Collector''s Edition for the true Far Cry fan experience, which includes the game, SteelBook case with alternate art, Season Pass, flamethrower replica, art book, exclusive in-game items, and more.' FROM games WHERE igdb_id = 149987 ON CONFLICT (game_id, language_code) DO NOTHING;
