INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ambition: A Minuet in Power', 'A young woman finds herself alone in the streets of Paris, far from home and abandoned by the love of her life. In that moment, she decides to live for herself and seek her own passions, as France marches towards a violent uprising that will change history forever. Navigate the twisting social politics of pre-revolutionary Paris in a game world that’s different every time you play. Court, snub and seduce your way to the top of society. Extend your influence, uncover the intrigue of the coming revolution, and ensure that you end up on the winning side of history.' FROM games WHERE igdb_id = 76255 ON CONFLICT (game_id, language_code) DO NOTHING;
