INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tunnel Blast', 'Tunnel Blast is a short action game with 25 levels where you fly a futuristic space jet through a series of tunnels. Supreme Chief Master Defensive Sergeant Dexter Charlington needs you to destroy the generator in the core of the planet, because it''s being controlled by an agressive AI. On your way through the five chapters you will go through different terrain and meet new dangers. Speed through every level and unlock gold medals to show off your prestige!' FROM games WHERE igdb_id = 142568 ON CONFLICT (game_id, language_code) DO NOTHING;
