INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ae', 'Strange shapes and voices pierce the blizzard''s veil, stranded and curious atop this mountain you leave behind the comforts of your cabin to survey this darkest of nights. A disconcerting pseudohorror walking journey through noisecore purgatories. Study the 5 glyphs of silence and cross the dead river with Wōden...' FROM games WHERE igdb_id = 184042 ON CONFLICT (game_id, language_code) DO NOTHING;
