INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('search-for-the-titanic', 69849, '2021-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21m4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aruv4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Search for the Titanic', 'Join the quest of the century in an authentic simulation that reflects man''s achievement landing. The search for the Titanic, the greatest ship to ever fall to the grip of the elements, has peaked man''s interest for decades. Experience the challenges and dangers, the excitement and reality of scientific under-water exploration as Search For The Titanic takes you on the quest to find the world''s most famous lost ship. Reviewed for authenticity by the staff of the Woods Hole Oceanographic Institution, the American organization that first discovered and photographed the Titanic wreck, Search For The Titanic contains digitized pictures from the actual photos of the Titanic, taken at a depth of more than 12,000 feet. 
