INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsuki''s Odyssey', 'Tsuki’s Odyssey is a passive adventure game that immerses you into the world of Tsuki and the oddball characters of Mushroom Village. Decorate your home, make friends, catch all kinds of fish and so much more! It is important to note that Tsuki is not your pet, but a free spirit who will move and interact with the world as they please. But if you check in often, you just might catch something new and exciting happening in the town!' FROM games WHERE igdb_id = 192101 ON CONFLICT (game_id, language_code) DO NOTHING;
