INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 6: Limited Edition', 'Welcome to Yara, a tropical paradise frozen in time. Far Cry 6 thrusts players into a modern-day guerrilla revolution. As dictator of Yara, Anton Castillo is intent on restoring his nation back to its former glory by any means, with his son, Diego, following in his bloody footsteps. Become a guerrilla fighter and liberate Yara. The Limited Edition of Far Cry 6 includes the entire game as well as the following digital content: The Jungle Expedition Pack.' FROM games WHERE igdb_id = 139867 ON CONFLICT (game_id, language_code) DO NOTHING;
